def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding up if the number is halfway between two integers.
    :param n: the number to round
    :return: the rounded number
    """
    if n % 1 == 0.5:
        return int(n) + 1
    else:
        return int(n)

