def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    # Initialize the result list
    result = []

    # Iterate over the input expressions
    for expr in args:
        # Check if the expression is a binary operator
        if isinstance(expr, BinaryOperator):
            # Get the operator and operands
            op, lhs, rhs = expr.operator, expr.lhs, expr.rhs

            # Check if the operator is a logical operator
            if op in [LogicalOperator.AND, LogicalOperator.OR]:
                # Check if the left operand is a logical operator
                if isinstance(lhs, LogicalOperator):
                    # Check if the left operand is a negation operator
                    if lhs == LogicalOperator.NOT:
                        # Apply negative absorption
                        if op == LogicalOperator.AND:
                            result.append(BinaryOperator(LogicalOperator.AND, lhs.operand, rhs))
                        elif op == LogicalOperator.OR:
                            result.append(BinaryOperator(LogicalOperator.OR, lhs.operand, rhs))
                    else:
                        # Apply absorption
                        if op == LogicalOperator.AND:
                            result.append(BinaryOperator(LogicalOperator.AND, lhs, rhs))
                        elif op == LogicalOperator.OR:
                            result.append(BinaryOperator(LogicalOperator.OR, lhs, rhs))
                else:
                    # Check if the right operand is a logical operator
                    if isinstance(rhs, LogicalOperator):
                        # Check if the right operand is a negation operator
                        if rhs == LogicalOperator.NOT:
                            # Apply negative absorption
                            if op == LogicalOperator.AND:
                                result.append(BinaryOperator(LogicalOperator.AND, lhs, rhs.operand))
                            elif op == LogicalOperator.OR:
                                result.append(BinaryOperator(LogicalOperator.OR, lhs, rhs.operand))
                        else:
                            # Apply absorption
                            if op == LogicalOperator.AND:
                                result.append(BinaryOperator(LogicalOperator.AND, lhs, rhs))
                            elif op == LogicalOperator.OR:
                                result.append(BinaryOperator(LogicalOperator.OR, lhs, rhs))
            else:
                # The expression is not a logical operator, so it is not affected by absorption
                result.append(expr)
        else:
            # The expression is not a binary operator, so it is not affected by absorption
            result.append(expr)

    # Return the result list
    return result

