def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    :param dic: A dictionary object to insert the nested key value into.
    :param val: A value to insert to the given dictionary.
    :param key: The first key in a chain of keys that will store the value.
    :param keys: Subkeys in the keys chain.
    """
    # Check if the input dictionary is valid
    if not isinstance(dic, dict):
        raise ValueError("Invalid input dictionary")

    # Check if the key is valid
    if not isinstance(key, str):
        raise ValueError("Invalid key")

    # Check if the value is valid
    if not isinstance(val, (str, int, float)):
        raise ValueError("Invalid value")

    # Check if the keys are valid
    for k in keys:
        if not isinstance(k, str):
            raise ValueError("Invalid key")

    # Insert the value into the dictionary
    current_dict = dic
    for k in keys:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]
    current_dict[key] = val

    return dic

