def validate_from_content(spec_content):
    """
    Validates that the spec (YAML) content has all required fields.

    :param spec_content: Content of the spec file.
    :return: Dictionary with data loaded from the spec (YAML) file.
    """
    # Check if the spec content is not None
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # Load the spec content into a dictionary
    spec_data = yaml.safe_load(spec_content)

    # Check if the spec data is not None
    if spec_data is None:
        raise IRValidatorException("Spec data is None")

    # Check if the spec data has the required fields
    required_fields = ["name", "version", "description", "license", "authors", "dependencies"]
    for field in required_fields:
        if field not in spec_data:
            raise IRValidatorException(f"Required field '{field}' is missing in spec data")

    # Check if the spec data has the correct data types
    if not isinstance(spec_data["name"], str):
        raise IRValidatorException(f"'name' field is not a string")
    if not isinstance(spec_data["version"], str):
        raise IRValidatorException(f"'version' field is not a string")
    if not isinstance(spec_data["description"], str):
        raise IRValidatorException(f"'description' field is not a string")
    if not isinstance(spec_data["license"], str):
        raise IRValidatorException(f"'license' field is not a string")
    if not isinstance(spec_data["authors"], list):
        raise IRValidatorException(f"'authors' field is not a list")
    if not all(isinstance(author, str) for author in spec_data["authors"]):
        raise IRValidatorException(f"'authors' field is not a list of strings")
    if not isinstance(spec_data["dependencies"], dict):
        raise IRValidatorException(f"'dependencies' field is not a dictionary")
    if not all(isinstance(dependency, str) for dependency in spec_data["dependencies"]):
        raise IRValidatorException(f"'dependencies' field is not a dictionary of strings")

    # Return the spec data
    return spec_data

